public Set getAllowedValues()
{
    var ret = new Set(Types::Integer);
    EcoResProductVariantConfiguration ecoResProductVariantConfiguration;
    while select RetailWeight from ecoResProductVariantConfiguration
        group by RetailWeight
    {
        ret.add(ecoResProductVariantConfiguration.RetailWeight);
    }
    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
